Here is the commit message:
RDMA/core: Validate cpu_id against nr_cpu_ids in DMAH alloc

The cpu_id attribute supplied by user space through
UVERBS_ATTR_ALLOC_DMAH_CPU_ID is passed directly to cpumask_test_cpu()
without first verifying that the value is within the valid CPU range.

Passing such untrusted data to cpumask_test_cpu() may lead to an
out-of-bounds read of the underlying cpumask bitmap: the helper expands
to a test_bit() that indexes the bitmap by cpu_id / BITS_PER_LONG with
no bound check.

In addition, on kernels built with CONFIG_DEBUG_PER_CPU_MAPS it trips
the WARN_ON_ONCE() in cpumask_check(); combined with panic_on_warn this
turns a bad user input into a machine reboot.

Reject any cpu_id that is not smaller than nr_cpu_ids with -EINVAL
before it is used.

Reported by Smatch.

Fixes: d83edab562a4 ("RDMA/core: Introduce a DMAH object and its alloc/free APIs")
Link: https://patch.msgid.link/r/20260525142136.28165-1-yishaih@nvidia.com
Cc: stable@vger.kernel.org
Reported-by: Dan Carpenter <error27@gmail.com>
Closes: https://lore.kernel.org/r/ag68qoAW3P04J7pT@stanley.mountain/
Signed-off-by: Yishai Hadas <yishaih@nvidia.com>
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>

Here is the root cause:
Missing validation of user-supplied cpu_id against nr_cpu_ids before passing it to cpumask_test_cpu(), allowing out-of-bounds read of the cpumask bitmap and triggering a WARN_ON with CONFIG_DEBUG_PER_CPU_MAPS.

Here is the patch:

 static int UVERBS_HANDLER(UVERBS_METHOD_DMAH_ALLOC)(
 	struct uverbs_attr_bundle *attrs)
 {
 	struct ib_uobject *uobj =
 		uverbs_attr_get(attrs, UVERBS_ATTR_ALLOC_DMAH_HANDLE)
 			->obj_attr.uobject;
 	struct ib_device *ib_dev = attrs->context->device;
 	struct ib_dmah *dmah;
 	int ret;

 	dmah = rdma_zalloc_drv_obj(ib_dev, ib_dmah);
 	if (!dmah)
 		return -ENOMEM;

 	if (uverbs_attr_is_valid(attrs, UVERBS_ATTR_ALLOC_DMAH_CPU_ID)) {
 		ret = uverbs_copy_from(&dmah->cpu_id, attrs,
 				       UVERBS_ATTR_ALLOC_DMAH_CPU_ID);
 		if (ret)
 			goto err;

+		if (dmah->cpu_id >= nr_cpu_ids) {
+			ret = -EINVAL;
+			goto err;
+		}
+
 		if (!cpumask_test_cpu(dmah->cpu_id, current->cpus_ptr)) {
 			ret = -EPERM;
 			goto err;
 		}

 		dmah->valid_fields |= BIT(IB_DMAH_CPU_ID_EXISTS);
 	}

 	if (uverbs_attr_is_valid(attrs, UVERBS_ATTR_ALLOC_DMAH_TPH_MEM_TYPE)) {
 		dmah->mem_type = uverbs_attr_get_enum_id(attrs,
 					UVERBS_ATTR_ALLOC_DMAH_TPH_MEM_TYPE);
 		dmah->valid_fields |= BIT(IB_DMAH_MEM_TYPE_EXISTS);
 	}

 	if (uverbs_attr_is_valid(attrs, UVERBS_ATTR_ALLOC_DMAH_PH)) {
 		ret = uverbs_copy_from(&dmah->ph, attrs,
 				       UVERBS_ATTR_ALLOC_DMAH_PH);
 		if (ret)
 			goto err;

 		/* Per PCIe spec 6.2-1.0, only the lowest two bits are applicable */
 		if (dmah->ph & 0xFC) {
 			ret = -EINVAL;
 			goto err;
 		}

 		dmah->valid_fields |= BIT(IB_DMAH_PH_EXISTS);
 	}

 	dmah->device = ib_dev;
 	dmah->uobject = uobj;
 	atomic_set(&dmah->usecnt, 0);

 	rdma_restrack_new(&dmah->res, RDMA_RESTRACK_DMAH);
 	rdma_restrack_set_name(&dmah->res, NULL);

 	ret = ib_dev->ops.alloc_dmah(dmah, attrs);
 	if (ret) {
 		rdma_restrack_put(&dmah->res);
 		goto err;
 	}

 	uobj->object = dmah;
 	rdma_restrack_add(&dmah->res);
 	uverbs_finalize_uobj_create(attrs, UVERBS_ATTR_ALLOC_DMAH_HANDLE);
 	return 0;
 err:
 	kfree(dmah);
 	return ret;
 }



